(function buildArrow() {
  const R = 1.15, w = 0.135, headW = 0.31, a0 = THREE.MathUtils.degToRad(172),
    a1 = THREE.MathUtils.degToRad(40), headSpan = THREE.MathUtils.degToRad(19);
  const aH = a1 + headSpan, N = 44, pts = [];
  for (let i = 0; i <= N; i++) { const a = a0 + (aH - a0) * i / N; pts.push(new THREE.Vector2(Math.cos(a) * (R + w), Math.sin(a) * (R + w))); }
  pts.push(new THREE.Vector2(Math.cos(aH) * (R + headW), Math.sin(aH) * (R + headW)));
  pts.push(new THREE.Vector2(Math.cos(a1) * R, Math.sin(a1) * R));
  pts.push(new THREE.Vector2(Math.cos(aH) * (R - headW), Math.sin(aH) * (R - headW)));
  for (let i = 0; i <= N; i++) { const a = aH + (a0 - aH) * i / N; pts.push(new THREE.Vector2(Math.cos(a) * (R - w), Math.sin(a) * (R - w))); }
  const shape = new THREE.Shape(); shape.setFromPoints(pts);
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({ color: 0xFBE3B4, side: THREE.DoubleSide }));
  arrowGroup.add(fill);
  const outlinePts = pts.map(p => new THREE.Vector3(p.x, p.y, 0.004));
  const og = new THREE.BufferGeometry().setFromPoints(outlinePts);
  arrowGroup.add(new THREE.LineLoop(og, new THREE.LineBasicMaterial({ color: 0x9A9A9A })));
  arrowGroup.position.y -= 0.5;
})();

