<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ─────────────────────────────────────────────────────────
   uv u-axis / v-axis        → CylinderGeometry shaft + ConeGeometry head, black
   u-constant line (uv)      → BoxGeometry(0.085, 3.25, 0.012) orange #F5A623
   v-constant line (uv)      → BoxGeometry(3.9, 0.085, 0.012) purple #B4569F
   uv crossing dot           → SphereGeometry(0.055) black
   mapping block arrow       → ShapeGeometry(arc band + head) #FBE3B4 + LineLoop #9A9A9A
   xyz axes x (depth), y, z  → CylinderGeometry shaft + screen-facing ShapeGeometry head, black
   surface patch             → BufferGeometry 40x40 parametric mesh, MeshLambert #DEDEDE (light)
   coordinate grid curves    → TubeGeometry r=0.014 MeshBasic #808080 (5 const-u + 4 const-v)
   constant-u curve          → TubeGeometry r=0.045 MeshBasic orange #F5A623
   constant-v curve          → TubeGeometry r=0.045 MeshBasic purple #B4569F
   image dot r(u0,v0)        → SphereGeometry(0.075) black
   all text                  → addLabel HTML overlays (serif italic variables)
   camera                    → oblique projection (y right, z up, x to lower-left)
  ────────────────────────────────────────────────────────────────────────── */

const C_ORANGE = 0xF5A623, C_PURPLE = 0xB4569F, C_GRID = 0x808080, C_BLACK = 0x111111;
const U_LO = 0.3, U_HI = 3.2, V_LO = 0.0, V_HI = 2.1;
const OBL_ANGLE = 54, OBL_DEPTH = 0.55;

/* ── lights (bright, so the patch reads as light gray like the source) ──── */
scene.add(new THREE.AmbientLight(0xffffff, 0.80));
const _dlA = new THREE.DirectionalLight(0xffffff, 0.38); _dlA.position.set(1.5, 4, 6); scene.add(_dlA);
const _dlB = new THREE.DirectionalLight(0xffffff, 0.14); _dlB.position.set(-4, -3, -4); scene.add(_dlB);

/* ── helpers ────────────────────────────────────────────────────────────── */
function disposeKids(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.traverse(o => {
      o.geometry?.dispose?.();
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
      else o.material?.dispose?.();
    });
  }
}
function makeArrowAxis(from, to, color, shaftR, headR, headL) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); dir.normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, Math.max(len - headL, 0.01), 12), mat);
  shaft.quaternion.copy(q);
  shaft.position.copy(from).addScaledVector(dir, (len - headL) / 2);
  g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 18), mat);
  head.quaternion.copy(q);
  head.position.copy(from).addScaledVector(dir, len - headL / 2);
  g.add(head);
  return g;
}

/* screen-facing arrowheads: a cone pointing along the DEPTH axis projects to a
   dot under the oblique projection, so the xyz axes use flat triangles that are
   re-aimed each frame along the axis's projected screen direction.            */
const screenHeads = [];
function makeScreenAxis(from, to, color, shaftR, headL, headW) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); dir.normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaftLen = Math.max(len - headL * 0.5, 0.01);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, shaftLen, 12), mat);
  shaft.quaternion.copy(q);
  shaft.position.copy(from).addScaledVector(dir, shaftLen / 2);
  g.add(shaft);
  const shape = new THREE.Shape();
  shape.moveTo(0, 0); shape.lineTo(-headL, headW); shape.lineTo(-headL, -headW); shape.closePath();
  const head = new THREE.Mesh(new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  head.position.copy(to);
  g.add(head);
  screenHeads.push({ head, tip: to.clone(), base: to.clone().addScaledVector(dir, -0.5) });
  return g;
}

function tubeFrom(pts, radius, color) {
  const clean = [];
  for (const p of pts) {
    if (!Number.isFinite(p.x) || !Number.isFinite(p.y) || !Number.isFinite(p.z)) continue;
    if (clean.length && clean[clean.length - 1].distanceToSquared(p) < 1e-10) continue;
    clean.push(p);
  }
  if (clean.length < 2) return null;
  const curve = new THREE.CatmullRomCurve3(clean);
  const geo = new THREE.TubeGeometry(curve, Math.max(24, clean.length), radius, 8, false);
  // MeshBasic: the curve colors must stay as saturated as the printed figure.
  return new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color }));
}

/* ── groups ─────────────────────────────────────────────────────────────── */
const uvGroup = new THREE.Group();    uvGroup.position.set(-5.9, -1.3, 0);   // billboarded
const arrowGroup = new THREE.Group(); arrowGroup.position.set(-1.0, 2.1, 0); // billboarded
const xyzGroup = new THREE.Group();   xyzGroup.position.set(1.3, -2.1, 0);

const surfGroup = new THREE.Group();
const gridGroup = new THREE.Group();
const hiUGroup = new THREE.Group();
const hiVGroup = new THREE.Group();
const dotGroup = new THREE.Group();
xyzGroup.add(surfGroup, gridGroup, hiUGroup, hiVGroup, dotGroup);

/* ── LEFT PANEL : uv parameter plane (local XY, billboarded) ─────────────── */
const U_SCALE = 1.0, V_SCALE = 1.0;
const U_AXIS_LEN = 3.9, V_AXIS_LEN = 2.9;

uvGroup.add(makeArrowAxis(new THREE.Vector3(-0.6, 0, 0), new THREE.Vector3(U_AXIS_LEN, 0, 0),
  C_BLACK, 0.026, 0.09, 0.26));
uvGroup.add(makeArrowAxis(new THREE.Vector3(0, -0.65, 0), new THREE.Vector3(0, V_AXIS_LEN, 0),
  C_BLACK, 0.026, 0.09, 0.26));

// parameter lines extend symmetrically PAST both axes (as in the source)
const U_LINE_LO = -0.55, U_LINE_HI = 2.75;   // vertical extent of the orange line
const V_LINE_LO = -0.55, V_LINE_HI = 3.35;   // horizontal extent of the purple line

const uLineMesh = new THREE.Mesh(
  new THREE.BoxGeometry(0.085, U_LINE_HI - U_LINE_LO, 0.012),
  new THREE.MeshBasicMaterial({ color: C_ORANGE }));
uLineMesh.position.set(0, (U_LINE_HI + U_LINE_LO) / 2, 0.006);
uvGroup.add(uLineMesh);

const vLineMesh = new THREE.Mesh(
  new THREE.BoxGeometry(V_LINE_HI - V_LINE_LO, 0.085, 0.012),
  new THREE.MeshBasicMaterial({ color: C_PURPLE }));
vLineMesh.position.set((V_LINE_HI + V_LINE_LO) / 2, 0, 0.006);
uvGroup.add(vLineMesh);

const uvDot = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 12),
  new THREE.MeshBasicMaterial({ color: C_BLACK }));
uvDot.position.z = 0.03;
uvGroup.add(uvDot);

/* ── MAPPING ARROW (curved block arrow, billboarded) ─────────────────────── */
(function buildArrow() {
  const R = 1.25, w = 0.15, headW = 0.34,
    a0 = THREE.MathUtils.degToRad(170), a1 = THREE.MathUtils.degToRad(38),
    headSpan = THREE.MathUtils.degToRad(19);
  const aH = a1 + headSpan, N = 46, pts = [];
  for (let i = 0; i <= N; i++) { const a = a0 + (aH - a0) * i / N; pts.push(new THREE.Vector2(Math.cos(a) * (R + w), Math.sin(a) * (R + w))); }
  pts.push(new THREE.Vector2(Math.cos(aH) * (R + headW), Math.sin(aH) * (R + headW)));
  pts.push(new THREE.Vector2(Math.cos(a1) * R, Math.sin(a1) * R));
  pts.push(new THREE.Vector2(Math.cos(aH) * (R - headW), Math.sin(aH) * (R - headW)));
  for (let i = 0; i <= N; i++) { const a = aH + (a0 - aH) * i / N; pts.push(new THREE.Vector2(Math.cos(a) * (R - w), Math.sin(a) * (R - w))); }
  const shape = new THREE.Shape(); shape.setFromPoints(pts);
  arrowGroup.add(new THREE.Mesh(new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({ color: 0xFCE3B0, side: THREE.DoubleSide })));
  const og = new THREE.BufferGeometry().setFromPoints(pts.map(p => new THREE.Vector3(p.x, p.y, 0.004)));
  arrowGroup.add(new THREE.LineLoop(og, new THREE.LineBasicMaterial({ color: 0x9A9A9A })));
})();

/* ── RIGHT PANEL : xyz axes  (figure z up, y right, x toward viewer) ─────── */
// figure coords (fx, fy, fz) → world (fy, fz, fx):  world X = y, world Y = z, world Z = x(depth)
function toWorld(fx, fy, fz) { return new THREE.Vector3(fy, fz, fx); }
const ORIGIN3 = new THREE.Vector3(0, 0, 0);
xyzGroup.add(makeScreenAxis(ORIGIN3, toWorld(0, 0, 4.2), C_BLACK, 0.026, 0.30, 0.105)); // z (up)
xyzGroup.add(makeScreenAxis(ORIGIN3, toWorld(0, 4.0, 0), C_BLACK, 0.026, 0.30, 0.105)); // y (right)
xyzGroup.add(makeScreenAxis(ORIGIN3, toWorld(2.5, 0, 0), C_BLACK, 0.026, 0.30, 0.105)); // x (front)

/* ── parametric evaluation (compiled from the equation inputs) ───────────── */
const F = { x: null, y: null, z: null };
const clampNum = t => (Number.isFinite(t) ? Math.max(-60, Math.min(60, t)) : 0);
function evalP(u, v) {
  let a = NaN, b = NaN, c = NaN;
  try { a = F.x(u, v); b = F.y(u, v); c = F.z(u, v); } catch (e) { }
  return toWorld(clampNum(a), clampNum(b), clampNum(c));
}
function normalAt(u, v) {
  const e = 1e-3, p = evalP(u, v);
  const pu = evalP(u + e, v).sub(p);
  const pv = evalP(u, v + e).sub(p);
  const n = new THREE.Vector3().crossVectors(pu, pv);
  if (n.lengthSq() < 1e-14) return new THREE.Vector3(0, 1, 0);
  n.normalize();
  if (n.y < 0) n.negate();     // always lift curves toward the viewer's side
  return n;
}
function sampleCurve(kind, val, n, off) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const u = kind === 'u' ? val : U_LO + (U_HI - U_LO) * t;
    const v = kind === 'u' ? V_LO + (V_HI - V_LO) * t : val;
    const p = evalP(u, v);
    if (off) p.addScaledVector(normalAt(u, v), off);
    pts.push(p);
  }
  return pts;
}

/* ── build / rebuild surface, grid, highlighted curves ───────────────────── */
const S = { view: 'both', u0: 1.6, v0: 1.0 };
let ready = false;

function buildSurface() {
  disposeKids(surfGroup);
  const N = 40, pos = [], idx = [];
  for (let i = 0; i <= N; i++) for (let j = 0; j <= N; j++) {
    const p = evalP(U_LO + (U_HI - U_LO) * i / N, V_LO + (V_HI - V_LO) * j / N);
    pos.push(p.x, p.y, p.z);
  }
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const a = i * (N + 1) + j, b = a + 1, c = a + N + 1, dd = c + 1;
    idx.push(a, c, b, b, c, dd);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals(); g.computeBoundingBox(); g.computeBoundingSphere();
  surfGroup.add(new THREE.Mesh(g, new THREE.MeshLambertMaterial({
    color: 0xDEDEDE, side: THREE.DoubleSide, transparent: true, opacity: 0.96
  })));
}

function buildGrid() {
  disposeKids(gridGroup);
  for (let k = 0; k <= 4; k++) {
    const u = U_LO + (U_HI - U_LO) * k / 4;
    const t1 = tubeFrom(sampleCurve('u', u, 60, 0.012), 0.014, C_GRID);
    if (t1) gridGroup.add(t1);
  }
  for (let k = 0; k <= 3; k++) {
    const v = V_LO + (V_HI - V_LO) * k / 3;
    const t2 = tubeFrom(sampleCurve('v', v, 60, 0.012), 0.014, C_GRID);
    if (t2) gridGroup.add(t2);
  }
}

function updateHighlights() {
  disposeKids(hiUGroup); disposeKids(hiVGroup); disposeKids(dotGroup);
  const pu = sampleCurve('u', S.u0, 80, 0.028);
  const tu = tubeFrom(pu, 0.045, C_ORANGE); if (tu) hiUGroup.add(tu);
  const pv = sampleCurve('v', S.v0, 80, 0.028);
  const tv = tubeFrom(pv, 0.045, C_PURPLE); if (tv) hiVGroup.add(tv);

  const cross = evalP(S.u0, S.v0).addScaledVector(normalAt(S.u0, S.v0), 0.055);
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.075, 18, 14),
    new THREE.MeshBasicMaterial({ color: C_BLACK }));
  dot.position.copy(cross);
  dotGroup.add(dot);

  // label anchors: back end of the orange curve, right end of the purple curve
  if (pu.length) labUCurve.local.copy(pu[0]);
  if (pv.length) labVCurve.local.copy(pv[pv.length - 1]);

  // uv-plane lines follow the same parameters
  const xu = S.u0 * U_SCALE, yv = S.v0 * V_SCALE;
  uLineMesh.position.x = xu;
  vLineMesh.position.y = yv;
  uvDot.position.set(xu, yv, 0.03);
  labUConst.local.set(xu, U_LINE_HI, 0);
  labVConst.local.set(xu + 1.15, yv, 0);
}

function rebuildAll(refit) {
  if (!F.x || !F.y || !F.z) return;
  buildSurface(); buildGrid(); updateHighlights();
  if (refit && ready) applyCamera();
}

/* ── labels ─────────────────────────────────────────────────────────────── */
const labelRefs = [];
const FAR = new THREE.Vector3(1e6, 1e6, 1e6);
function mkLabel(html, local, group, visFn, opts) {
  const entry = addLabel(html, FAR, opts || {});
  const ref = { entry, local: local.clone(), group: group || null, vis: visFn };
  labelRefs.push(ref);
  return ref;
}
const IT = s => '<i style="font-family:Georgia,\'Times New Roman\',serif">' + s + '</i>';
const uvVisible = () => uvGroup.parent === scene;
const xyzVisible = () => xyzGroup.parent === scene;

mkLabel(IT('u'), new THREE.Vector3(U_AXIS_LEN, 0, 0), uvGroup, uvVisible,
  { fontSize: '19px', offset: [2, -22] });
mkLabel(IT('v'), new THREE.Vector3(0, V_AXIS_LEN, 0), uvGroup, uvVisible,
  { fontSize: '19px', offset: [20, -2] });
const labUConst = mkLabel(IT('u') + ' constant', new THREE.Vector3(), uvGroup, uvVisible,
  { fontSize: '17px', offset: [58, -14] });
const labVConst = mkLabel(IT('v') + ' constant', new THREE.Vector3(), uvGroup, uvVisible,
  { fontSize: '17px', offset: [0, -20] });

mkLabel(IT('z'), toWorld(0, 0, 4.2), xyzGroup, xyzVisible, { fontSize: '19px', offset: [16, -6] });
mkLabel(IT('y'), toWorld(0, 4.0, 0), xyzGroup, xyzVisible, { fontSize: '19px', offset: [8, -22] });
mkLabel(IT('x'), toWorld(2.5, 0, 0), xyzGroup, xyzVisible, { fontSize: '19px', offset: [18, 18] });
const labUCurve = mkLabel('Constant ' + IT('u') + '-curve', new THREE.Vector3(), xyzGroup, xyzVisible,
  { fontSize: '16px', offset: [86, -22] });
const labVCurve = mkLabel('Constant<br>' + IT('v') + '-curve', new THREE.Vector3(), xyzGroup, xyzVisible,
  { fontSize: '16px', offset: [60, 18] });

/* ── hover / click explanations ─────────────────────────────────────────── */
registerInteractive(surfGroup, {
  title: 'The parametric surface r(u, v)',
  tooltip: 'The image of the uv-rectangle under r',
  body: 'Every point (u, v) of the flat parameter rectangle is carried by r(u,v) = ⟨x(u,v), y(u,v), z(u,v)⟩ to a point of this sheet in space. The whole rectangle is bent into the gray patch.'
});
registerInteractive(hiUGroup, {
  title: 'Constant u-curve',
  tooltip: 'u is fixed, v varies',
  body: 'Freezing u = u₀ and letting v run gives the single-variable vector function v ↦ r(u₀, v): a curve lying entirely on the surface. It is the image of the vertical orange line in the uv-plane.'
});
registerInteractive(hiVGroup, {
  title: 'Constant v-curve',
  tooltip: 'v is fixed, u varies',
  body: 'Freezing v = v₀ and letting u run gives u ↦ r(u, v₀), the image of the horizontal purple line in the uv-plane. The two families of such curves form the curvilinear grid drawn on the surface.'
});
registerInteractive(dotGroup, {
  title: 'The image point r(u₀, v₀)',
  tooltip: 'r(u₀, v₀)',
  body: 'The two parameter lines meet at the single pair (u₀, v₀), so their images meet at the single point r(u₀, v₀) on the surface.'
});

/* ── equation inputs (parsing owned by the scaffold) ─────────────────────── */
bindEquationInput('xComp', (fn) => { F.x = fn; rebuildAll(true); }, { variables: ['u', 'v'] });
bindEquationInput('yComp', (fn) => { F.y = fn; rebuildAll(true); }, { variables: ['u', 'v'] });
bindEquationInput('zComp', (fn) => { F.z = fn; rebuildAll(true); }, { variables: ['u', 'v'] });

/* ── camera / view switching ─────────────────────────────────────────────── */
function syncBillboards() {
  uvGroup.quaternion.copy(camera.quaternion);
  arrowGroup.quaternion.copy(camera.quaternion);
  uvGroup.updateMatrixWorld(true);
  arrowGroup.updateMatrixWorld(true);
}
function applyCamera() {
  if (S.view === 'uv-domain') {
    setCameraView({ projection: 'orthographic', axisScreenAngles: null, heightFraction: 0.80 });
    controls.enableRotate = false;
  } else if (S.view === 'xyz-surface') {
    setCameraView({
      projection: 'oblique', obliqueAngleDeg: OBL_ANGLE, depthScale: OBL_DEPTH,
      heightFraction: 0.82
    });
    controls.enableRotate = true;
  } else {
    setCameraView({
      projection: 'oblique', obliqueAngleDeg: OBL_ANGLE, depthScale: OBL_DEPTH,
      heightFraction: 0.90
    });
    controls.enableRotate = true;
  }
}
const viewBtns = {
  'uv-domain': document.getElementById('btnViewUV'),
  'xyz-surface': document.getElementById('btnViewXYZ'),
  'both': document.getElementById('btnViewBoth')
};
function setView(v) {
  S.view = v;
  scene.remove(uvGroup); scene.remove(xyzGroup); scene.remove(arrowGroup);
  if (v === 'uv-domain') scene.add(uvGroup);
  else if (v === 'xyz-surface') scene.add(xyzGroup);
  else { scene.add(uvGroup); scene.add(arrowGroup); scene.add(xyzGroup); }
  for (const k in viewBtns) viewBtns[k].classList.toggle('active', k === v);
  applyCamera(); syncBillboards(); applyCamera();
}
for (const k in viewBtns) viewBtns[k].addEventListener('click', () => setView(k));

/* ── sliders ─────────────────────────────────────────────────────────────── */
const uSlider = document.getElementById('uParam');
const vSlider = document.getElementById('vParam');
const uValOut = document.getElementById('uVal');
const vValOut = document.getElementById('vVal');
function setU(val, moveSlider) {
  S.u0 = val; uValOut.textContent = val.toFixed(2);
  if (moveSlider) uSlider.value = String(val);
  updateHighlights();
}
function setV(val, moveSlider) {
  S.v0 = val; vValOut.textContent = val.toFixed(2);
  if (moveSlider) vSlider.value = String(val);
  updateHighlights();
}
uSlider.addEventListener('input', () => setU(parseFloat(uSlider.value), false));
vSlider.addEventListener('input', () => setV(parseFloat(vSlider.value), false));

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    t: 'A map from the uv-plane to space',
    n: 'Left: the flat parameter plane. Right: its image under r(u,v). The big arrow is the map itself — it bends the whole rectangle of (u,v) pairs into the gray patch.',
    v: 'both', u: 1.60, vv: 1.00
  },
  {
    t: 'Two lines in the parameter plane',
    n: 'Fixing u = u₀ gives a vertical orange line; fixing v = v₀ gives a horizontal purple line. They cross at the single parameter pair (u₀, v₀).',
    v: 'uv-domain', u: 1.60, vv: 1.00
  },
  {
    t: 'Their images on the surface',
    n: 'Apply r. The straight lines become curves lying on the surface, crossing at the single image point r(u₀, v₀). The orange one bends because z changes with v.',
    v: 'xyz-surface', u: 1.60, vv: 1.00
  },
  {
    t: 'Sweeping u builds one family',
    n: 'Slide u: the orange constant-u curve slides across the patch. The whole family of these curves is one set of the gray grid lines drawn on the surface.',
    v: 'both', u: 2.70, vv: 1.00
  },
  {
    t: 'Sweeping v builds the other family',
    n: 'Now slide v: the purple constant-v curve sweeps transversally. Together the two families form the natural curvilinear coordinate grid of the parametrization.',
